namespace CppCompiler
{
    public enum TokenType
    {
        // C subset
        INT, VOID, CHAR, FLOAT, DOUBLE, SHORT, LONG,
        SIGNED, UNSIGNED, BOOL,
        IF, ELSE, WHILE, FOR, DO, SWITCH, CASE, DEFAULT,
        RETURN, BREAK, CONTINUE, GOTO,
        ENUM, STRUCT, UNION, CONST, STATIC, EXTERN, TYPEDEF,
        SIZEOF, VOLATILE, REGISTER, AUTO, INLINE,
        ASM, INTERRUPT, NULLPTR,
        STDCALL, FASTCALL, CDECL,
        // C99 fixed-width types
        SIZE_T, SSIZE_T, PTRDIFF_T,
        INT8, INT16, INT32, INT64,
        UINT8, UINT16, UINT32, UINT64,
        INTPTR_T,         UINTPTR_T, RESTRICT,
        WCHAR_T, CHAR32_T,

        // C++ keywords
        CLASS, NAMESPACE, TEMPLATE, TYPENAME,
        PUBLIC, PRIVATE, PROTECTED,
        NEW, DELETE, VIRTUAL, OVERRIDE, OPERATOR, EXPLICIT,
        THIS, FRIEND, MUTABLE, CONSTEXPR, CONSTEVAL, STATIC_ASSERT, NOEXCEPT,
        TRY, CATCH, THROW,
        USING, VIRTUAL_INHERIT,

        // Identifiers & literals
        IDENTIFIER, NUMBER, STRING, WSTRING, USTRING, CHAR_LITERAL, WCHAR_LITERAL, UCHAR_LITERAL,

        // Operators
        PLUS, MINUS, STAR, SLASH, PERCENT,
        AMPERSAND, PIPE, CARET, TILDE,
        INCREMENT, DECREMENT,
        LSHIFT, RSHIFT, LSHIFT_ASSIGN, RSHIFT_ASSIGN,
        SCOPE_RESOLVE, ARROW_STAR, DOT_STAR,

        ASSIGN, ADD_ASSIGN, SUB_ASSIGN, MUL_ASSIGN, DIV_ASSIGN, MOD_ASSIGN,
        AND_ASSIGN, OR_ASSIGN, XOR_ASSIGN,
        EQ, NE, LT, LE, GT, GE,
        AND, OR, NOT,

        DOT, ARROW, ELLIPSIS, QUESTION, COLON,

        LPAREN, RPAREN, LBRACE, RBRACE, LBRACKET, RBRACKET,
        COMMA, SEMICOLON, HASH, HASHHASH,

        EOF, ERROR
    }
}
